import { RootStore } from "./RootStore";
import { SettingStore } from "./SettingStore";

// entry 跟 slot_game 是各自編譯的 bundle 各有一份這個模組
// 用模組內變數擋不住兩邊各自建立一份 RootStore 這裡改存 globalThis 讓兩邊認到同一份
const ROOT_STORE_KEY = '__APP_ROOT_STORE__';

export function createRootStore(): RootStore {
    const existing = (globalThis as any)[ROOT_STORE_KEY] as RootStore | undefined;
    if (existing) return existing;
    console.warn("[RootStore] createRootStore");
    const instance = new RootStore();
    (globalThis as any)[ROOT_STORE_KEY] = instance;
    return instance;
}

export function getSettingStore(): SettingStore | null {
    const instance = (globalThis as any)[ROOT_STORE_KEY] as RootStore | undefined;
    return instance?.setting ?? null;
}
