import { _decorator, Color, Component, Label, sp, Sprite, UITransform } from 'cc';
import { SymbolExtras, SymbolState } from './SymbolState';
import { getSymbolScale } from '../../config/SlotGameDefinition';

const { ccclass } = _decorator;

// Flame 消除線框的縮放
const FLAME_SCALE_X = 0.55;
const FLAME_SCALE_Y = 0.59;

/**
 * 顯示層基底：一顆「某個符號的某個狀態」的畫面物件，由 {@link SymbolImageManager} 租借與回收。
 *
 * 設計依據：entry repo `docs/SlotSymbolSystem_設計參考.md` §5.1。
 *
 * **這一層只暴露幾個動作**——`onRent` / `onReturn` / `resetAni` / `playOnce` / `setColor` /
 * `setTimeScale` / `applyExtras`——而且刻意不知道自己是用 Sprite、Spine 還是別的技術畫出來的。
 * 規格書 §15.1 第 4 點把這件事列為整套架構能同時支援多種美術管線的關鍵：邏輯層只會呼叫這幾個，
 * 換渲染方案不必動任何遊戲邏輯。
 *
 * 基底版本負責靜態圖：節點上有 `Sprite` 就套顏色，沒有就什麼都不做。需要播動畫的狀態由
 * {@link SymbolViewSpine} 之類的子類接手。
 */
@ccclass('1001/SymbolView')
export class SymbolView extends Component {
    /** 這顆物件屬於哪個符號 id，由 manager 在租借時寫入 */
    public symbolId: number = 0;

    /** 這顆物件代表哪個狀態，由 manager 在租借時寫入 */
    public state: SymbolState = SymbolState.None;

    /**
     * 回收時要放回哪個池。
     *
     * 用模板節點的 uuid 而不是 `symbolId × 1000 + state` 當歸還鍵，是因為 fallback 會讓多個狀態
     * 共用同一份模板（例如 `Blur` 缺項時頂替 `Normal`）。若照租借時的狀態歸還，同一份模板做出來的
     * 物件會被拆進不同的池，池與池之間互相要不到對方閒置的物件，數量只增不減。
     */
    public poolKey: string = '';

    /**
     * 這顆物件底下所有的繪製元件，`setColor` 要一次套到全部。
     *
     * 一個狀態節點通常不只一個繪製元件——中獎狀態同時有「符號本體的 Skeleton」與「火焰框的
     * Skeleton」，倍率球則是「球的 Skeleton」加上「數字的 Label」，壓黑時都要一起暗下來。
     * 在 {@link initImage} 抓一次存起來，不要每次 `setColor` 都重新 `getComponentsInChildren`。
     *
     * `Label` 是 1001 才需要收的（1003 的符號上沒有文字）：舊 `SlotMachineView.tweenSymbolColor()`
     * 為了倍率球數字特地繞過去抓 `NgSymbol.coinLabel`，收進來之後那條特例就不必存在。
     */
    protected sprites: Sprite[] = [];
    protected skeletons: sp.Skeleton[] = [];
    protected labels: Label[] = [];

    /**
     * 第一次被 instantiate 出來時呼叫一次，之後租借／回收都不會再進來。
     *
     * 抓元件這類只需要做一次的事放這裡，不要放 `onRent`——後者每次租借都會跑。
     */
    public initImage(): void {
        this.sprites = this.getComponentsInChildren(Sprite);
        this.skeletons = this.getComponentsInChildren(sp.Skeleton);
        this.labels = this.getComponentsInChildren(Label);
        this.onInit();
    }

    /**
     * 從池裡被租出去、掛到格子上時呼叫。
     *
     * @param symbolId 這次要顯示哪個符號。
     */
    public onRent(symbolId: number): void {
        this.symbolId = symbolId;
        this.applySymbolScale(symbolId);
        this.node.active = true;
        // 貼圖是直接 alpha 預乘要關 開著邊緣半透明處會變成一團光
        for (const skeleton of this.skeletons) skeleton.premultipliedAlpha = false;
        this.setColor(Color.WHITE);
        this.resetAni();
    }

    /** 靜態圖與動效套同一個縮放 */
    private applySymbolScale(symbolId: number): void {
        const scale = getSymbolScale(symbolId);
        for (const sprite of this.sprites) {
            const size = sprite.spriteFrame?.originalSize;
            if (size) sprite.getComponent(UITransform)?.setContentSize(size.width * scale, size.height * scale);
        }
        for (const skeleton of this.skeletons) {
            const isFlame = skeleton.node.name === 'Flame';
            skeleton.node.setScale(isFlame ? FLAME_SCALE_X : scale, isFlame ? FLAME_SCALE_Y : scale, 1);
        }
    }

    /** 被歸還回池裡時呼叫，子類要在這裡把動畫、計時器、tween 全部停掉 */
    public onReturn(): void {
        this.node.active = false;
    }

    /** 重播動畫。靜態圖沒有動畫可播，子類覆寫 */
    public resetAni(): void {
        // 基底無動畫
    }

    /**
     * 播一次並在結束時回呼。
     *
     * 基底是靜態圖，沒有「播完」這回事，所以立刻回呼——呼叫端（`SymbolCell.playCurrentStateOnce`）
     * 另外掛了保底計時器，兩邊都會呼叫同一個只生效一次的收尾函式。
     *
     * @param onComplete 播完時呼叫。
     */
    public playOnce(onComplete: () => void): void {
        onComplete();
    }

    /**
     * 調整動畫播放速度。靜態圖沒有速度可調，子類覆寫。
     *
     * @param _scale 倍率，1 為原速。
     */
    public setTimeScale(_scale: number): void {
        // 基底無動畫
    }

    /**
     * 回填格子常駐保存的附加參數。
     *
     * 只有倍率球用得到（見 {@link SymbolExtras}）；其餘符號的長相完全由 prefab 決定，
     * 基底什麼都不做。
     *
     * @param _extras 附加參數；null 表示這一格沒有。
     */
    public applyExtras(_extras: SymbolExtras | null): void {
        // 基底無附加參數
    }

    /**
     * 套用相乘顏色。
     *
     * 壓黑與所有調色都必須走這裡，不可以在外面直接寫 `Sprite.color`——那正是盤點文件
     * （`.docs/1003-symbol-system-gap-analysis.md` 第二節第 6 條）記錄的「一個通道兩個主人」問題，
     * 1001 的版本更嚴重：舊 `tweenSymbolColor()` 同時 tween Sprite、Skeleton、Label 與 jpBadge 四種
     * 元件，任何一條別的路徑寫同一個通道都會被它蓋掉。
     *
     * @param color 目標顏色。
     */
    public setColor(color: Color): void {
        for (const sprite of this.sprites) sprite.color = color;
        for (const skeleton of this.skeletons) skeleton.color = color;
        for (const label of this.labels) label.color = color;
    }

    /** 子類的一次性初始化掛點，由 {@link initImage} 呼叫 */
    protected onInit(): void {
        // 子類覆寫
    }
}
