import {
    GAME_EVENT_ID,
    GAME_EVENT_TYPE,
    gameRuntimeEventBus,
} from "../../events/GameRuntimeEventBus";

export default class TemplateStore {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('store/TemplateStore') */
    public readonly $modelType = 'store/TemplateStore';

    private _winBalance = 0;
    /**
     * 本局贏分。
     *
     * @returns 贏分。
     */
    get winBalance(): number { return this._winBalance; }
    /**
     * 更新本局贏分並發 WIN_BALANCE_CHANGED；跟目前相同時直接略過。
     *
     * @param winBalance 贏分。
     */
    setWinBalance(winBalance: number): void {
        if (this._winBalance === winBalance) return;
        this._winBalance = winBalance;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.WIN_BALANCE_CHANGED, {
            eventId: GAME_EVENT_ID.WIN_BALANCE_CHANGED,
            winBalance,
        });
    }

    private _betBalance = 0;
    /**
     * 目前的下注額。
     *
     * @returns 下注額。
     */
    get betBalance(): number { return this._betBalance; }

    private _betIndex = 0;
    /**
     * 目前下注額在注額表裡的位置。
     *
     * @returns 索引。
     */
    get betIndex(): number { return this._betIndex; }
    /**
     * 只改索引、不連動下注額。要一起改請用 changeBetIndex()。
     *
     * @param betIndex 索引。
     */
    setBetIndex(betIndex: number): void { this._betIndex = betIndex; }

    private _betLeavel: string[] = [];
    /**
     * 後端給的可選注額表（字串避免浮點誤差）。
     *
     * @returns 注額表。
     */
    get betLeavel(): string[] { return this._betLeavel; }
    /**
     * 換掉可選注額表。
     *
     * @param betLeavel 注額表。
     */
    setBetLeavel(betLeavel: string[]): void { this._betLeavel = betLeavel; }

    /** 保留建構子參數是為了相容 TemplateViewModel 裡 `new TemplateModel({})` 的舊呼叫方式 */
    constructor(_props?: unknown) {}

    /**
     * 更新下注額並發 BET_BALANCE_CHANGED；跟目前相同時直接略過。
     *
     * @param betBalance 下注額。
     */
    setBetBalance(betBalance: number): void {
        if (this._betBalance === betBalance) return;
        this._betBalance = betBalance;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.BET_BALANCE_CHANGED, {
            eventId: GAME_EVENT_ID.BET_BALANCE_CHANGED,
            betBalance,
        });
    }

    /**
     * 往上調一階注額；已經在最高階就不動。
     */
    addBetLevel() {
        this._betIndex = this._betIndex >= this._betLeavel.length - 1 ? this._betIndex : this._betIndex + 1;
        this.setBetBalance(Number(this._betLeavel[this._betIndex]));
    }
    /**
     * 往下調一階注額；已經在最低階就不動。
     */
    minusBetLevel() {
        this._betIndex = this._betIndex <= 0 ? this._betIndex : this._betIndex - 1;
        this.setBetBalance(Number(this._betLeavel[this._betIndex]));
    }
    /**
     * 直接跳到注額表的某一階，並同步更新下注額。
     *
     * @param index 注額表索引。
     */
    changeBetIndex(index: number) {
        this._betIndex = index;
        this.setBetBalance(Number(this._betLeavel[index]));
    }

    /**
     * 反查目前下注額落在注額表的哪一階。
     *
     * @returns 索引；注額表裡沒有相符的值時回 -1。
     */
    getCurrentIndex() {
        for (let i = 0; i < this._betLeavel.length; i++) {
            if (Number(this._betLeavel[i]) === this._betBalance) {
                return i;
            }
        }
        return -1;
    }


}
